import os

# 扫描工程目录
base_path = r"F:\qgis_project"
results = []

for root, dirs, files in os.walk(base_path):
    for f in files:
        ext = os.path.splitext(f)[1].lower()
        if ext in ['.shp', '.geojson', '.gpkg', '.csv', '.tif', '.tiff', '.dem', '.gpx', '.json', '.kml', '.xlsx', '.xls']:
            full_path = os.path.join(root, f)
            results.append(full_path)

if results:
    print("找到以下数据文件：")
    for r in results:
        print(r)
else:
    print("在 F:\\qgis_project 下未找到 GIS 数据文件")

# 也检查 autoc/downloads
downloads = r"autoc\downloads"
if os.path.exists(downloads):
    for root, dirs, files in os.walk(downloads):
        for f in files:
            ext = os.path.splitext(f)[1].lower()
            if ext in ['.shp', '.geojson', '.gpkg', '.csv', '.tif', '.tiff', '.dem', '.gpx', '.json', '.kml', '.xlsx', '.xls']:
                full_path = os.path.join(root, f)
                results.append(full_path)
    if results:
        print("\n找到数据文件（含 downloads）：")
        for r in results:
            print(r)
else:
    print("\nautoc/downloads 目录不存在")
